$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$stmt=db()->prepare('SELECT mr.*,CONCAT(c.first_name," ",c.last_name) AS client_name FROM mutual_requests mr JOIN dossiers d ON d.id=mr.dossier_id JOIN clients c ON c.id=d.client_id WHERE mr.id=?');$stmt->execute([$id]);$request=$stmt->fetch();if(!$request){http_response_code(404);exit('Demande introuvable.');}
