</span><input type="datetime-local" name="response_at" value="<?= e(($request['response_at']?:$request['response_received_at'])?date('Y-m-d\TH:i',strtotime($request['response_at']?:$request['response_received_at'])):'') ?>"></label><label class="field"><span>Valide jusqu’au</span><input type="date" name="valid_until" value="<?= e($request['valid_until']??'') ?>"></label><label class="field"><span>Justificatif lié</span><select name="document_id"><option value="">—</option><?php foreach($documents as $document):?><option value="<?= (int)$document['id'] ?>" <?= $request['document_id']==$document['id']?'selected':'' ?>><?= e($document['original_file_name']?:$document['original_name']) ?></option><?php endforeach;?></select></label><label class="field field-full"><span>Motif de refus</span><input name="refusal_reason" value="<?= e($request['refusal_reason']??'') ?>"></label></div></section>
